def _generate_expression(self):
    # Validate that all braces are properly matched
    # Check for unbalanced braces
    depth = 0
    in_field = False
    i = 0
    fmt = self._format

    while i < len(fmt):
        c = fmt[i]
        if c == '{':
            if i + 1 < len(fmt) and fmt[i+1] == '{':
                # Escaped {{ - skip both
                i += 2
                continue
            elif not in_field:
                depth += 1
                in_field = True
            else:
                raise ValueError('malformed format string - nested opening brace')
        elif c == '}':
            if i + 1 < len(fmt) and fmt[i+1] == '}':
                # Escaped }} - skip both
                i += 2
                continue
            elif in_field:
                depth -= 1
                if depth < 0:
                    raise ValueError('malformed format string - unmatched closing brace')
                in_field = False
            else:
                raise ValueError('malformed format string - unmatched closing brace')
        i += 1

    if in_field or depth > 0:
        raise ValueError('malformed format string - unclosed brace(s)')

    # turn my _format attribute into the _expression attribute
    e = []
    for part in PARSE_RE.split(self._format):
        if not part:
            continue
        elif part == '{{':
            e.append(r'\{')
        elif part == '}}':
            e.append(r'\}')
        elif part[0] == '{':
            # this will be a braces-delimited field to handle
            e.append(self._handle_field(part))
        else:
            # just some text to match
            e.append(REGEX_SAFETY.sub(self._regex_replace, part))
    return ''.join(e)

